   } catch(Throwable $ex) {if($db->inTransaction()) $db->rollBack();throw $ex;}
   $_SESSION['notice']='ลบโครงการ '.count($deleteIds).' โครงการ พร้อมรายชื่อ เทมเพลต และรายการภาพแล้ว เลขที่เคยออกจะไม่ถูกนำกลับมาใช้ซ้ำ';
   go('?page=dashboard');
  }
  if($action==='project') {
   $title=trim($_POST['title']??'');$date=$_POST['date']??'';$endDate=$_POST['end_date']??$date;
   if(!$title || !preg_match('/^\d{4}-\d{2}-\d{2}$/',$date) || date('Y-m-d',strtotime($date))!==$date || !trim($_POST['owner']??'')) throw new RuntimeException('กรุณาระบุชื่อโครงการ วันที่ และผู้รับผิดชอบให้ถูกต้อง');
   if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$endDate) || date('Y-m-d',strtotime($endDate))!==$endDate || $endDate<$date) throw new RuntimeException('วันสิ้นสุดต้องเป็นวันที่ถูกต้องและไม่อยู่ก่อนวันเริ่มโครงการ');
   $eventType=$_POST['event_type']??($id?(rows('SELECT event_type FROM projects WHERE id=?',[$id])[0]['event_type']??'training'):'training');if(!isset($eventTypes[$eventType])) throw new RuntimeException('ประเภทงานไม่ถูกต้อง');
