    // Excel may append empty columns; organization is optional (name,role or name,organization,role).
    $header=array_map(fn($v)=>strtolower(trim((string)$v)),$header);while($header && end($header)==='') array_pop($header);
    $columns=['name,role'=>[0,null,1],'name,organization,role'=>[0,1,2]][implode(',',$header)]??null;if(!$columns) throw new RuntimeException('หัวตารางต้องเป็น name,role หรือ name,organization,role');
    while(($r=fgetcsv($h,0,',','"',''))!==false) {$r=array_map(fn($v)=>trim((string)$v),$r);if(!array_filter($r,fn($v)=>$v!=='')) continue;if(count($r)<count($header) || array_filter(array_slice($r,count($header)),fn($v)=>$v!=='')) throw new RuntimeException('ข้อมูลแต่ละแถวต้องมี '.count($header).' คอลัมน์ตามหัวตาราง');$entries[]=[$r[$columns[0]],$columns[1]===null?'':$r[$columns[1]],$r[$columns[2]]];if(count($entries)>5000) throw new RuntimeException('นำเข้าได้ไม่เกิน 5,000 รายชื่อต่อครั้ง');}fclose($h);
   }
   foreach($entries as $r) if(!$r[0] || !isset($roles[$r[2]]) || !mb_check_encoding(implode('',$r),'UTF-8')) throw new RuntimeException('ตรวจสอบชื่อ ประเภท (participant, speaker, committee, general) และการเข้ารหัส UTF-8');
   $db->beginTransaction();$added=0;foreach($entries as $r) {$s=$db->prepare('INSERT INTO recipients(project_id,name,organization,role,token) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE id=id');$s->execute([$id,...$r,bin2hex(random_bytes(16))]);$added+=$s->rowCount();}$db->commit();$_SESSION['notice']='เพิ่มรายชื่อ '.$added.' คน • ข้ามรายชื่อซ้ำ '.(count($entries)-$added).' คน';go('?page=project&id='.$id.'&tab=people');
  }
  if($action==='publish') {run('UPDATE projects SET published=? WHERE id=?',[(int)!empty($_POST['published']),$id]);go('?page=project&id='.$id);}
