   beginNumberingTransaction();
   try {
    $removed=0;$released=0;
    foreach($recipientIds as $recipientId) {
     $recipient=rows('SELECT certificate_number,central_sequence,sequence_year FROM recipients WHERE id=? AND project_id=?',[$recipientId,$id])[0]??null;
     if(!$recipient) continue;
