     run('DELETE FROM recipients WHERE id=? AND project_id=?',[$recipientId,$id]);$removed++;
    }
    $db->commit();
   } catch(Throwable $ex) {$db->rollBack();throw $ex;}
   $_SESSION['notice']=$action==='revoke'?'เพิกถอนและลบข้อมูลผู้รับแล้ว คืนเลขเดิมสำหรับการออกครั้งถัดไป':'ลบรายชื่อ '.$removed.' คน คืนเลขที่ '.$released.' เลขสำหรับการออกครั้งถัดไป';
