    try {run('INSERT INTO templates(project_id,role,heading,background) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE background=VALUES(background)',[$id,$role,$role==='general'?'เพื่อแสดงว่าได้รับเกียรติบัตร':'เพื่อแสดงว่าได้เป็น'.$roles[$role].'ในงานนี้',$file]);}
    catch(Throwable $ex) {if(is_file(__DIR__.'/data/'.$file)) unlink(__DIR__.'/data/'.$file);throw $ex;}
   } elseif(empty($_POST['clear_background'])) throw new RuntimeException('กรุณาเลือกภาพพื้นหลังที่ต้องการอัปโหลด');
