</tr></thead><tbody><?php foreach($people as $r):?><tr><td><input type="checkbox" name="recipient_ids[]" value="<?=$r['id']?>" form="bulk-revoke" data-person-selection aria-label="เลือก <?=e($r['name'])?>"></td><td><strong><?=e($r['name'])?></strong><small><?=e($r['organization'])?></small><small><?=e($r['certificate_number']??'ยังไม่ออกเลขที่')?></small></td><td><?=$roles[$r['role']]?></td><td><span class="badge <?=$r['issued']?'':'draft'?>"><?=$r['issued']?'ออกแล้ว':'ฉบับร่าง'?></span></td><td><?php if(!$r['record_only']):?><a class="text-link" target="_blank" href="?page=certificate&token=<?=$r['token']?>">ดูเกียรติบัตร ↗</a><?php else:?><span class="muted">ทะเบียนเลขเท่านั้น</span><?php endif ?><?php if($r['certificate_number']!==null):?><form class="inline" method="post"><?=csrf()?><input type="hidden" name="action" value="revoke"><input type="hidden" name="recipient_id" value="<?=$r['id']?>"><button class="link-button">เพิกถอน / คืนเลขและลบข้อมูล</button></form><?php endif ?></td></tr><?php endforeach ?><?php if(!$people):?><tr><td colspan="5" class="empty">ยังไม่มีรายชื่อ เพิ่มหรือนำเข้ารายชื่อเพื่อเริ่มออกเกียรติบัตร</td></tr><?php endif ?></tbody></table></div></section><script>
 document.addEventListener('DOMContentLoaded',function(){
  const all=document.getElementById('select-all-people'),items=Array.from(document.querySelectorAll('[data-person-selection]')),form=document.getElementById('bulk-revoke');
  if(!form) return;
  function update(){const n=items.filter(x=>x.checked).length;document.getElementById('selected-people-count').textContent='เลือกแล้ว '+n+' รายชื่อ';all.checked=n===items.length;all.indeterminate=n>0&&n<items.length;form.querySelector('button').disabled=n===0;}
  all.addEventListener('change',function(){items.forEach(x=>x.checked=all.checked);update();});items.forEach(x=>x.addEventListener('change',update));update();
 });
</script>
