 document.addEventListener('DOMContentLoaded',function(){
  const all=document.getElementById('select-all-projects'),items=Array.from(document.querySelectorAll('[data-project-selection]')),form=document.getElementById('bulk-delete-projects');
  function update(){const n=items.filter(x=>x.checked).length;document.getElementById('selected-project-count').textContent='เลือกแล้ว '+n+' โครงการ';all.checked=n===items.length;all.indeterminate=n>0&&n<items.length;form.querySelector('button').disabled=n===0;}
