dif ?></div><?php if($isDash && userRole()==='admin'):?><details><summary class="link-button">ลบโครงการ</summary><form method="post"><?=csrf()?><input type="hidden" name="action" value="delete_project"><input type="hidden" name="project_id" value="<?=$p['id']?>"><p>ลบโครงการนี้พร้อมรายชื่อ เกียรติบัตร เทมเพลต และรายการภาพ ลิงก์เกียรติบัตรจะใช้ไม่ได้ เลขที่ออกแล้วจะไม่ถูกคืนเพื่อใช้ซ้ำ</p><label class="check"><input type="checkbox" name="confirm_delete" value="1" required> ยืนยันลบโครงการนี้</label><button type="submit">ยืนยันลบโครงการ</button></form></details><?php endif ?></article><?php endforeach ?></div><?php endif ?></section><?php endif ?><footer><a href="?page=guide">คู่มือการใช้งาน</a> · <a href="?page=privacy">นโยบายความเป็นส่วนตัว (PDPA)</a> · <span class="app-version">v<?=e(CERTHUB_VERSION)?></span> · © <?=date('Y')+543?> CertHub · วิทยาลัยการอาชีพโพนทอง <span>สร้างโอกาสแห่งการเรียนรู้ เก็บความภูมิใจไว้ด้วยกัน</span><div class="developer-credit">ผู้พัฒนาระบบ: <?=e(CERTHUB_DEVELOPER)?> · <?=e(CERTHUB_DEVELOPER_POSITION)?></div></footer></div></main></body></html>
